func enrichRunSummary(ctx context.Context, cfg reviewtypes.RunConfig, summary reviewtypes.RunSummary) (out reviewtypes.RunSummary) {
	if cfg.EnrichSummary == nil {
		return summary
	}
	// EnrichSummary is a caller-supplied callback; a panic here would crash
	// the run after agents have already done their work. Recover and fall
	// back to the un-enriched summary so the dump and sinks still see results.
	defer func() {
